CREATE TABLE public.profile_photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, storage_path text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), CHECK (split_part(storage_path, '/', 1) = user_id::text));
GRANT SELECT, INSERT, DELETE ON public.profile_photos TO authenticated;
GRANT ALL ON public.profile_photos TO service_role;
ALTER TABLE public.profile_photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own photos" ON public.profile_photos FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "Insert own photos" ON public.profile_photos FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id AND EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id = 'avatars' AND name = storage_path));
CREATE POLICY "Delete own photos" ON public.profile_photos FOR DELETE TO authenticated USING (auth.uid() = user_id);
CREATE INDEX profile_photos_user ON public.profile_photos(user_id, created_at);
CREATE TABLE public.profesor_ai_review_eligibility (user_id uuid PRIMARY KEY, first_success_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profesor_ai_review_eligibility TO authenticated;
GRANT ALL ON public.profesor_ai_review_eligibility TO service_role;
ALTER TABLE public.profesor_ai_review_eligibility ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own review eligibility" ON public.profesor_ai_review_eligibility FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE TABLE public.profesor_ai_reviews (user_id uuid PRIMARY KEY, rating smallint NOT NULL CHECK (rating BETWEEN 1 AND 5), comment text NOT NULL DEFAULT '' CHECK (char_length(comment) <= 500), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profesor_ai_reviews TO authenticated;
GRANT ALL ON public.profesor_ai_reviews TO service_role;
ALTER TABLE public.profesor_ai_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own AI review" ON public.profesor_ai_reviews FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "Insert eligible AI review" ON public.profesor_ai_reviews FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id AND EXISTS (SELECT 1 FROM public.profesor_ai_review_eligibility WHERE user_id = auth.uid()));
CREATE POLICY "Update eligible AI review" ON public.profesor_ai_reviews FOR UPDATE TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id AND EXISTS (SELECT 1 FROM public.profesor_ai_review_eligibility WHERE user_id = auth.uid()));
CREATE TRIGGER ai_review_touch BEFORE UPDATE ON public.profesor_ai_reviews FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();